const N = 256;
const BYTES = 8;            // double
const LINE = 64;            // cache line bytes
const PER_LINE = LINE / BYTES; // 8 doubles per line
const a = new Float64Array(N * N); // row-major flatten: idx = i*N + j
for (let k = 0; k < a.length; k++) a[k] = 1;

function lineOf(i, j) { return Math.floor((i * N + j) / PER_LINE); }

// Row-major: inner loop j strides contiguously (+1 element)
let sumA = 0, missA = 0, prevA = -1;
for (let i = 0; i < N; i++) {
  for (let j = 0; j < N; j++) {
    const line = lineOf(i, j);
    if (line !== prevA) { missA++; prevA = line; }
    sumA += a[i * N + j];
  }
}

// Column-major: inner loop i strides N elements => new line every step
let sumB = 0, missB = 0, prevB = -1;
for (let j = 0; j < N; j++) {
  for (let i = 0; i < N; i++) {
    const line = lineOf(i, j);
    if (line !== prevB) { missB++; prevB = line; }
    sumB += a[i * N + j];
  }
}

console.log('sums equal:', sumA === sumB);
console.log('row-major line touches   :', missA);
console.log('column-major line touches:', missB);
console.log('ratio:', (missB / missA).toFixed(2) + 'x');

